package minheap

import "testing"

func TestPushPop(t *testing.T) {
	h := New()
	h.Push(5)
	h.Push(3)
	h.Push(8)
	h.Push(1)
	v, ok := h.Pop()
	if !ok || v != 1 { t.Fatalf("want 1, got %d ok=%v", v, ok) }
	v, ok = h.Pop()
	if !ok || v != 3 { t.Fatalf("want 3, got %d ok=%v", v, ok) }
}

func TestPeek(t *testing.T) {
	h := New()
	h.Push(7)
	h.Push(2)
	v, ok := h.Peek()
	if !ok || v != 2 { t.Fatalf("want 2, got %d", v) }
	if h.Len() != 2 { t.Fatal("peek should not remove element") }
}

func TestEmptyPop(t *testing.T) {
	h := New()
	_, ok := h.Pop()
	if ok { t.Fatal("pop on empty heap should return ok=false") }
}

func TestLen(t *testing.T) {
	h := New()
	if h.Len() != 0 { t.Fatal("new heap should have len 0") }
	h.Push(1)
	h.Push(2)
	if h.Len() != 2 { t.Fatalf("want 2, got %d", h.Len()) }
	h.Pop()
	if h.Len() != 1 { t.Fatalf("want 1, got %d", h.Len()) }
}

func TestSortOrder(t *testing.T) {
	h := New()
	for _, v := range []int{9, 4, 7, 1, 6, 2} {
		h.Push(v)
	}
	prev := -1
	for h.Len() > 0 {
		v, _ := h.Pop()
		if v < prev { t.Fatalf("out of order: %d after %d", v, prev) }
		prev = v
	}
}
